<script setup lang="ts">
import { computed,onMounted,ref,watch } from 'vue'
import { useRoute } from 'vue-router'
import AdminClassDialog from './AdminClassDialog.vue'
import SiteDialog from '@/features/management-shared/SiteDialog.vue'
import {getAdminApi,statusLabel,type AdminRow} from './api'
const api=getAdminApi(),courses=ref<AdminRow[]>([]),classes=ref<AdminRow[]>([]),teachers=ref<AdminRow[]>([]),tab=ref('courses'),query=ref(''),status=ref('all'),term=ref('all'),course=ref('all'),error=ref(''),busy=ref(false),modal=ref(''),selected=ref<AdminRow>(),preview=ref<Record<string,unknown>>(),transfer=ref({teacher_id:0,keep_previous:true,reason:''})
const confirmationName=ref(''),deletionReceipt=ref<{operation_id:string;cleanup_pending:boolean;cleanup_id?:string}>()
const route=useRoute()
function openLinkedClass(){
  if(route.query.tab!=='classes')return
  tab.value='classes'
  const row=classes.value.find(item=>String(item.id)===route.query.class_id)
  if(row)open('detail',row)
}
watch(()=>[route.query.tab,route.query.class_id],openLinkedClass)
const deletionLabels:Record<string,string>={classes:'班级',banks:'题库',questions:'题目',question_links:'题目知识点映射',question_identities:'题目标识',import_previews:'导入预览',concepts:'知识点',experiments:'实验定义',plans:'发布计划',participants:'参与者快照',tasks:'班级任务',schedules:'排期修订',sessions:'已开始会话',attempts:'作答记录',events:'过程事件',submissions:'交卷任务',exports:'导出任务',snapshots:'导出快照',assets:'研究资产',coverage:'采集覆盖评估',members:'协作关系',enrollments:'选课关系',access_periods:'选课访问历史',subjects:'课程研究标识',study_links:'研究项目关联',imports:'学生导入记录',cleanup_receipts:'保留的清理回执'}
const form=ref({name:'',code:'',term:'',description:'',owner_id:0,course_id:0,academic_year:''})
const filtered=computed(()=>(tab.value==='courses'?courses.value:classes.value).filter(x=>[x.name,x.code,x.owner_name,x.course_name].join(' ').toLowerCase().includes(query.value.trim().toLowerCase())&&(tab.value==='courses'?(status.value==='all'||x.status===status.value)&&(term.value==='all'||x.term===term.value):(course.value==='all'||String(x.course_id)===course.value))))
async function load(){try{const [c,g,u]=await Promise.all([api.get<{items:AdminRow[]}>('courses/'),api.get<{items:AdminRow[]}>('classes/'),api.get<{items:AdminRow[]}>('users/')]);courses.value=c.items;classes.value=g.items;teachers.value=u.items.filter(x=>x.role==='teacher'&&x.is_active)}catch(e){error.value=(e as Error).message}}
onMounted(async()=>{await load();openLinkedClass()})
function open(kind:string,row?:AdminRow){error.value='';preview.value=undefined;modal.value=kind;selected.value=row;if(kind==='detail'&&tab.value==='classes'){modal.value='class';return};form.value={name:row?.name||'',code:row?.code||'',term:row?.term||'',description:row?.description||'',owner_id:row?.owner_id||0,course_id:row?.course_id||0,academic_year:row?.academic_year||''}}
async function mutate(path:string,body:unknown){busy.value=true;error.value='';try{await api.post(path,body);modal.value='';await load()}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function submit(){await mutate(modal.value==='create'?(tab.value==='courses'?'courses/':'classes/'):`courses/${selected.value?.id}/update/`,{...form.value,state_token:selected.value?.state_token})}
async function confirmDeletion(){if(confirmationName.value!==selected.value?.name)return;busy.value=true;error.value='';try{deletionReceipt.value=await api.post(`courses/${selected.value?.id}/delete/`,{confirmation:'DELETE',confirmation_name:confirmationName.value,confirmation_token:preview.value?.confirmation_token});modal.value='';await load()}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function deletion(){confirmationName.value='';busy.value=true;error.value='';try{preview.value=await api.post<Record<string,unknown>>(`courses/${selected.value?.id}/delete-preview/`,{});modal.value='delete'}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
</script>
<template>
  <div class="eyebrow">COURSES &amp; CLASSES</div><header class="heading"><div><h1>课程与班级</h1><p>跨课程查看教学组织，分别管理课程、班级和选课关系。</p></div><button class="primary" @click="open('create')">＋ {{ tab==='courses'?'新建课程':'新建班级' }}</button></header>
  <div v-if="deletionReceipt" role="status" class="policy-note"><div><strong>课程已删除。</strong><br>{{ deletionReceipt.cleanup_pending ? '文件清理仍在后台处理中，可在实验与数据页面查看清理状态。' : '文件清理已完成。' }}<br>操作回执：{{ deletionReceipt.operation_id }}<template v-if="deletionReceipt.cleanup_id"><br>清理编号：{{ deletionReceipt.cleanup_id }}</template></div></div>
  <p v-if="error&&!modal" role="alert" class="error-block">{{ error }}</p>
  <section class="card"><div class="tabs"><button :class="{active:tab==='courses'}" @click="tab='courses';query=''">课程目录 <em>{{ courses.length }}</em></button><button :class="{active:tab==='classes'}" @click="tab='classes';query=''">班级目录 <em>{{ classes.length }}</em></button></div><div class="toolbar multi-filter"><div class="search"><input v-model="query" aria-label="搜索课程与班级" placeholder="搜索课程名称、代码或负责人"></div><div class="filter-group"><template v-if="tab==='courses'"><select v-model="term" aria-label="学期"><option value="all">全部学期</option><option v-for="t in [...new Set(courses.map(x=>x.term))]" :key="t" :value="t">{{ t }}</option></select><select v-model="status" aria-label="课程状态"><option value="all">全部状态</option><option value="active">进行中</option><option value="archived">已归档</option></select></template><select v-else v-model="course" aria-label="筛选课程"><option value="all">全部课程</option><option v-for="c in courses" :key="c.id" :value="String(c.id)">{{ c.name }}</option></select></div></div><div class="table-scroll"><table><thead><tr><th>{{ tab==='courses'?'课程':'班级' }}</th><th>{{ tab==='courses'?'负责人':'所属课程' }}</th><th>{{ tab==='courses'?'班级 / 学生':'选课人数' }}</th><th>状态</th><th>管理</th></tr></thead><tbody><tr v-for="row in filtered" :key="row.id"><td><strong class="cell-title">{{ row.name }}</strong><small class="cell-sub">{{ tab==='courses'?`${row.code} · ${row.term}`:`${row.academic_year} 级` }}</small></td><td>{{ tab==='courses'?row.owner_name:row.course_name }}</td><td><template v-if="tab==='courses'">{{ row.class_count }} 个班级<small class="cell-sub">{{ row.student_count ?? 0 }} 位学生 · 课程内去重</small></template><template v-else>{{ row.student_count ?? 0 }} 人</template></td><td><span class="badge" :class="{gray:row.status==='archived'||row.is_active===false}">{{ tab==='courses'?statusLabel(row):row.is_active?'启用中':'已停用' }}</span></td><td><button class="link" @click="open('detail',row)">{{ tab==='courses'?'管理课程':'成员与任务' }}</button><button v-if="tab==='courses'" class="link" @click="course=String(row.id);tab='classes';query=''">班级 →</button></td></tr><tr v-if="!filtered.length"><td class="empty" colspan="5">没有匹配结果，请调整筛选条件。</td></tr></tbody></table></div><div class="table-footer"><span>共 {{ filtered.length }} {{ tab==='courses'?'门课程':'个班级' }}</span><span>课程成员关系与平台账号独立管理</span></div></section><div class="policy-note"><div><strong>归档保留历史，删除先看影响</strong><br>移除选课或删除班级不会直接删除学生账号。正式任务与历史作答通过专门流程管理。</div></div>
  <SiteDialog :open="Boolean(modal) && modal!=='class'" :title="modal==='create'?(tab==='courses'?'新建课程':'新建班级'):modal==='edit'?'编辑基础信息':modal==='delete'?'课程删除影响':selected?.name||'课程管理'" :subtitle="selected?.code" @close="modal=''"><form v-if="modal==='create'||modal==='edit'" id="admin-course-form" class="form-grid" @submit.prevent="submit"><label class="field">{{ tab==='courses'?'课程名称':'班级名称' }}<input v-model="form.name" required></label><template v-if="tab==='courses'"><div class="two-fields"><label class="field">课程代码<input v-model="form.code" required></label><label class="field">学期<input v-model="form.term" required></label></div><label v-if="modal==='create'" class="field">负责人<select v-model="form.owner_id" required><option :value="0" disabled>选择教师</option><option v-for="t in teachers" :key="t.id" :value="t.id">{{ t.name }} · {{ t.username }}</option></select></label><label class="field">课程说明<textarea v-model="form.description" rows="3" /></label></template><template v-else><label class="field">所属课程<select v-model="form.course_id" required><option :value="0" disabled>选择课程</option><option v-for="c in courses" :key="c.id" :value="c.id">{{ c.name }}</option></select></label><label class="field">年级<input v-model="form.academic_year" pattern="[0-9]{4}" placeholder="四位年份" required></label></template></form><template v-else-if="modal==='detail'&&selected"><dl class="detail-list"><div><dt>{{ tab==='courses'?'负责人':'所属课程' }}</dt><dd>{{ selected.owner_name || selected.course_name }}</dd></div><div><dt>资源范围</dt><dd>{{ selected.class_count ?? 0 }} 个班级 · {{ selected.experiment_count ?? 0 }} 个实验 · {{ selected.student_count ?? 0 }} 位学生</dd></div><div><dt>说明</dt><dd>{{ selected.description || '暂无说明' }}</dd></div></dl><div v-if="tab==='courses'" class="action-grid"><button @click="open('edit',selected)">编辑基础信息</button><button @click="modal='transfer';transfer={teacher_id:0,keep_previous:true,reason:''}">移交负责人</button><a class="management-action-link" :href="selected.settings_url">协作权限管理 →</a><button @click="modal=selected.status==='archived'?'restore':'archive'">{{ selected.status==='archived'?'恢复课程':'归档课程' }}</button><button class="danger" :disabled="busy" @click="deletion">查看删除影响</button></div><a v-else class="management-action-link" :href="selected.detail_url">管理成员与班级任务 →</a></template><form v-else-if="modal==='transfer'" id="course-transfer" class="form-grid" @submit.prevent="mutate(`courses/${selected?.id}/transfer/`,{...transfer,state_token:selected?.collaboration_token})"><label class="field">新负责人<select v-model="transfer.teacher_id" required><option :value="0" disabled>选择教师</option><option v-for="t in teachers.filter(t=>t.id!==selected?.owner_id)" :key="t.id" :value="t.id">{{ t.name }} · {{ t.username }}</option></select></label><label><input v-model="transfer.keep_previous" type="checkbox">原负责人保留为协作教师</label><label class="field">移交原因<textarea v-model="transfer.reason" required rows="3" /></label></form><template v-else-if="modal==='delete'"><dl class="detail-list"><div v-for="(count,key) in (preview?.counts as Record<string,number>)" :key="key"><dt>{{ deletionLabels[key] || key }}</dt><dd>{{ count }}</dd></div></dl><p class="hint">{{ preview?.blocked_reason || '删除上述课程关联内容，保留平台账号、其他课程和最小审计记录。删除不可撤销。' }}</p><label v-if="preview?.allowed" class="field">输入课程名称确认<input v-model="confirmationName" name="confirmation_name" :placeholder="selected?.name" autocomplete="off"></label></template><p v-else>{{ modal==='archive'?'归档后课程变为只读，学生不能开始新的实验会话。':'恢复课程后重新开放课程管理。' }}</p><p v-if="error" role="alert" class="error-block">{{ error }}</p><template #footer><button @click="modal=''">取消</button><button v-if="modal==='create'||modal==='edit'" class="primary" form="admin-course-form" type="submit" :disabled="busy">保存</button><button v-if="modal==='archive'||modal==='restore'" class="primary" :disabled="busy" @click="mutate(`courses/${selected?.id}/${modal}/`,{confirmation:modal})">确认变更</button><button v-if="modal==='transfer'" class="primary" form="course-transfer" type="submit" :disabled="busy||!transfer.teacher_id">确认移交</button><button v-if="modal==='delete'&&preview?.allowed" class="danger" :disabled="busy||confirmationName!==selected?.name" @click="confirmDeletion">确认删除</button></template></SiteDialog>
  <AdminClassDialog :row="modal==='class'?selected:undefined" @close="modal=''" @changed="load" />
</template>
